import{_ as o,o as s,c as t,a3 as a}from"./chunks/framework.DAK02U1-.js";const m=JSON.parse('{"title":"Vendor SDKs","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Vendor SDKs | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/design/vendor-sdks"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/design/vendor-sdks"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/design/vendor-sdks"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/design/vendor-sdks"}]]},"headers":[],"relativePath":"xclang/design/vendor-sdks.md","filePath":"en/xclang/design/vendor-sdks.md","lastUpdated":1791301679000}'),n={name:"xclang/design/vendor-sdks.md"};function i(d,e,r,c,h,l){return s(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="vendor-sdks" tabindex="-1">Vendor SDKs <a class="header-anchor" href="#vendor-sdks" aria-label="Permalink to &quot;Vendor SDKs&quot;">​</a></h1><p>Some targets need an SDK that only its vendor may distribute: Apple&#39;s for macOS, and Microsoft&#39;s MSVC libraries and Windows SDK for the MSVC ABI.</p><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>xclang never redistributes a vendor SDK. Its design is that the user fetches it from the vendor, by a pinned version and digest, after accepting the vendor&#39;s license. The command for that is <code>xclang sdk fetch</code>, which every toolchain archive carries (<a href="./../reference/xclang-command">the xclang command</a>). The targets that need it are the MSVC targets, and the macOS targets on Linux and Windows hosts; on macOS hosts, the macOS targets use the installed Xcode&#39;s SDK. The SDK in use is a link in the toolchain&#39;s <code>sdk/</code>, so config files name a fixed path while versions change (<a href="./../reference/xclang-command#the-sdk-in-use">the SDK in use</a>).</p><h2 id="why-fetch-not-ship" tabindex="-1">Why Fetch, Not Ship <a class="header-anchor" href="#why-fetch-not-ship" aria-label="Permalink to &quot;Why Fetch, Not Ship&quot;">​</a></h2><p>Apple&#39;s SDK agreement and Microsoft&#39;s Visual Studio license allow use, not redistribution. A toolchain that bundles them, or a Docker image that contains them, passes them on. cross-rs, for one, provides no images for Apple targets &quot;due to licensing reasons&quot;, and leaves building one to the user.</p><p>xclang goes the other way. It downloads from the vendor&#39;s own servers, so each user gets the SDK from the vendor, under the vendor&#39;s terms, and xclang&#39;s archives stay free to share. For the user of <code>xclang sdk fetch</code>, that means:</p><ul><li>It prints the vendor&#39;s license terms and stops, until given <code>--accept-license</code>.</li><li>Apple&#39;s terms allow use of the SDK on Apple hardware. Building for macOS from Linux or Windows with it is the user&#39;s decision under those terms; xclang does not make it for them.</li><li>Versions are pinned. <code>cli/sdk-versions.json</code>, built into the program, lists every version the vendors offer, with sizes and sha256. Its presets match GitHub&#39;s runner images (<code>macos-latest</code>, <code>windows-2022</code>, ...), so a cross build gets what a workflow on that image gets.</li></ul><h2 id="apple-s-sdk-without-xcode" tabindex="-1">Apple&#39;s SDK without Xcode <a class="header-anchor" href="#apple-s-sdk-without-xcode" aria-label="Permalink to &quot;Apple&#39;s SDK without Xcode&quot;">​</a></h2><p>The macOS SDK is in Apple&#39;s Command Line Tools package, on <code>swcdn.apple.com</code>. Apple&#39;s software update catalogs name it, and no Apple ID is needed. The package is a xar archive. Its payload is pbzx, a stream of xz chunks, holding a cpio archive. xclang reads all three with its own code, a few hundred lines, so the fetch works on every host without macOS tools. Man pages, tools and Perl are left out.</p><p>On Linux and Windows hosts, the config files of the macOS targets use the SDK in use, <code>sdk/macos</code>; on macOS hosts, Xcode&#39;s (<a href="./macos#the-sdk-on-linux-and-windows-hosts">macOS</a>). The Command Line Tools hold the SDK and its compilers, not Xcode&#39;s other tools: app bundles&#39; asset catalogs and nibs, which need <code>actool</code> and <code>ibtool</code>, do not build off macOS.</p><p><strong>The iOS family is a hard limit.</strong> The SDKs for iOS, tvOS, watchOS, visionOS and their simulators come only with full Xcode, downloaded with an Apple ID. No unattended fetch can get them. So those targets are <a href="./roadmap#ios">in research</a>, and are likely to need their runtimes built on demand.</p><h2 id="microsoft-s-sdk-without-visual-studio" tabindex="-1">Microsoft&#39;s SDK without Visual Studio <a class="header-anchor" href="#microsoft-s-sdk-without-visual-studio" aria-label="Permalink to &quot;Microsoft&#39;s SDK without Visual Studio&quot;">​</a></h2><p>The MSVC CRT and STL come from Visual Studio&#39;s own <code>.vsix</code> packages, named in its channel manifest. The Windows SDK comes from NuGet&#39;s <code>Microsoft.Windows.SDK.CPP</code> packages. Both are zip archives.</p><p>The usual route is Visual Studio&#39;s installer, or the MSI and CAB files of the SDK. It needs Windows, or tools that read MSI and CAB. Zips are read by xclang&#39;s own code on every host. The files are laid out as Visual Studio installs them, for <code>/winsysroot</code>.</p><p>xwin is the known tool for this, and unpacks the MSI and CAB route. Against it, nothing these builds need was missing. xwin also has no macOS or Windows-on-Arm binaries, which xclang needed.</p><p>On a case-sensitive file system, links are added for the spellings that Windows code uses (<code>windows.h</code>, <code>WinBase.h</code> as <code>winbase.h</code>, <code>LIBCMT.lib</code>, ...). So code written on Windows builds unchanged.</p><p>Download and unpacked sizes are in <a href="./../reference/xclang-command#vendor-sdks">the xclang command</a>.</p>',18)])])}const u=o(n,[["render",i]]);export{m as __pageData,u as default};
